<div class="row g-3"><div class="col-xl-7"><div class="card"><div class="card-header"><h5 class="mb-0">Buat Surat Tunggakan</h5></div><div class="card-body"><div class="row g-2 align-items-end"><div class="col-md-10"><input id="q" class="form-control" placeholder="Cari siswa nama / NIS / NISN"></div><div class="col-md-2 d-grid"><button id="cari" class="btn btn-primary"><i class="ri-search-line me-1"></i>Cari</button></div></div><div id="hasil" class="mt-3"></div><div id="identitas" class="alert alert-primary mt-3 d-none"></div><div id="formArea" class="d-none"><div class="row g-2 mb-3"><div class="col-md-4"><select id="periode" class="form-select"><option value="">Semua Tahun Ajaran</option><?php foreach($periode as $p): ?><option value="<?= $p['id'] ?>"><?= html_escape($p['periode']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select id="batasBulan" class="form-select"><?php for($i=1;$i<=12;$i++): ?><option value="<?= $i ?>" <?= $i==date('n')?'selected':'' ?>>Sampai <?= nama_bulan($i) ?></option><?php endfor ?></select></div><div class="col-md-3"><input type="number" id="batasTahun" class="form-control" value="<?= date('Y') ?>"></div><div class="col-md-2 d-grid"><button id="muat" class="btn btn-secondary">Muat</button></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th><input type="checkbox" id="all"></th><th>Tagihan</th><th>Periode</th><th class="text-end">Nominal</th><th class="text-end">Dibayar</th><th class="text-end">Sisa</th></tr></thead><tbody id="tagihan"><tr><td colspan="6" class="empty-state">Muat tagihan.</td></tr></tbody></table></div></div></div></div></div><div class="col-xl-5"><div class="card sticky-summary"><div class="card-header"><h5 class="mb-0">Informasi Surat</h5></div><div class="card-body"><div class="d-flex justify-content-between mb-3"><strong>Total dalam Surat</strong><strong class="text-danger fs-18" id="total">Rp0</strong></div><div class="mb-2"><label class="form-label">Tanggal Surat</label><input id="tanggal" class="form-control tanggal-picker" value="<?= date('d-m-Y') ?>" autocomplete="off"></div><div class="mb-2"><label class="form-label">Nama Penandatangan</label><input id="namaTtd" class="form-control" value="Bendahara Sekolah"></div><div class="mb-2"><label class="form-label">Jabatan</label><input id="jabatanTtd" class="form-control" value="Bendahara"></div><div class="mb-3"><label class="form-label">Catatan</label><textarea id="catatan" class="form-control" rows="3"></textarea></div><div class="d-grid"><button id="simpan" class="btn btn-success" disabled>Simpan & Preview Surat</button></div></div></div></div></div>
<div class="card"><div class="card-header"><h5 class="mb-0">Riwayat Surat</h5></div><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>No Surat</th><th>Tanggal</th><th>Siswa</th><th>Kelas</th><th class="text-end">Total</th><th>Status WA</th><th>Aksi</th></tr></thead><tbody id="riwayat"></tbody></table></div></div></div>
<script>$(function(){flatpickr('.tanggal-picker',{dateFormat:'d-m-Y',allowInput:true,disableMobile:true});let siswa=null,rows=[];const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');function search(){let q=$('#q').val();if(q.trim().length<2)return Swal.fire('Perhatian','Masukkan minimal 2 karakter.','warning');$.post('<?= base_url('surat_tunggakan/cari_siswa') ?>',{q},r=>$('#hasil').html(r.length?'<div class="list-group">'+r.map(x=>`<button class="list-group-item list-group-item-action pilih" data-json='${escapeHtml(JSON.stringify(x))}'><strong>${escapeHtml(x.nama_lengkap)}</strong><br><small>${escapeHtml(x.nis+' | '+(x.nama_kelas||'-'))}</small></button>`).join('')+'</div>':'<div class="alert alert-warning">Siswa tidak ditemukan.</div>'),'json')}$('#cari').click(search);$('#q').keypress(e=>{if(e.which===13)search()});$(document).on('click','.pilih',function(){siswa=JSON.parse($(this).attr('data-json'));$('#hasil').empty();$('#identitas').removeClass('d-none').html(`<strong>${escapeHtml(siswa.nama_lengkap)}</strong><br>${escapeHtml(siswa.nis+' | '+(siswa.nama_kelas||'-'))}<br>Ayah: ${escapeHtml(siswa.telepon_ayah||'-')} | Ibu: ${escapeHtml(siswa.telepon_ibu||'-')}`);$('#formArea').removeClass('d-none');loadBills()});function loadBills(){$.post('<?= base_url('surat_tunggakan/tagihan') ?>',{id_siswa:siswa.id,id_periode:$('#periode').val(),batas_bulan:$('#batasBulan').val(),batas_tahun:$('#batasTahun').val()},r=>{rows=r;$('#tagihan').html(r.length?r.map(x=>`<tr><td><input type="checkbox" class="form-check-input cek" value="${x.id}"></td><td><strong>${escapeHtml(x.nama_tagihan)}</strong><br><small>${escapeHtml(x.no_tagihan)}</small></td><td>${escapeHtml((x.nama_bulan||'')+' '+x.tahun)}<br><small>${escapeHtml(x.periode)}</small></td><td class="text-end">${money(x.nominal_tagihan)}</td><td class="text-end">${money(x.nominal_dibayar)}</td><td class="text-end fw-semibold">${money(x.sisa_tagihan)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">Tidak ada tagihan wajib yang masih tersisa.</td></tr>');calc()},'json')}$('#muat').click(loadBills);$('#all').change(function(){$('.cek').prop('checked',this.checked);calc()});$(document).on('change','.cek',calc);function calc(){let ids=$('.cek:checked').map((_,x)=>Number(x.value)).get(),t=rows.filter(x=>ids.includes(Number(x.id))).reduce((a,x)=>a+Number(x.sisa_tagihan),0);$('#total').text(money(t));$('#simpan').prop('disabled',!ids.length||!siswa)}$('#simpan').click(()=>{let ids=$('.cek:checked').map((_,x)=>Number(x.value)).get();$.post('<?= base_url('surat_tunggakan/simpan') ?>',{id_siswa:siswa.id,tagihan:JSON.stringify(ids),tanggal_surat:$('#tanggal').val(),batas_bulan:$('#batasBulan').val(),batas_tahun:$('#batasTahun').val(),nama_penandatangan:$('#namaTtd').val(),jabatan_penandatangan:$('#jabatanTtd').val(),catatan:$('#catatan').val()},r=>{if(r.result!=='true')return Swal.fire('Gagal',r.message,'error');Swal.fire('Berhasil',r.message,'success').then(()=>window.open('<?= base_url('surat_tunggakan/cetak/') ?>'+r.id,'_blank'));history()},'json').fail(ajaxError)});function history(){$.getJSON('<?= base_url('surat_tunggakan/riwayat') ?>',r=>$('#riwayat').html(r.length?r.map(x=>`<tr><td><strong>${escapeHtml(x.no_surat)}</strong></td><td>${escapeHtml(x.tanggal_surat)}</td><td>${escapeHtml(x.nama_siswa)}<br><small>${escapeHtml(x.nis)}</small></td><td>${escapeHtml(x.nama_kelas)}</td><td class="text-end fw-semibold">${money(x.total_tunggakan)}</td><td>${escapeHtml(x.status_kirim_whatsapp)}</td><td><div class="action-buttons"><a target="_blank" href="<?= base_url('surat_tunggakan/cetak/') ?>${x.id}" class="btn btn-sm btn-primary">Preview/Cetak</a><button class="btn btn-sm btn-success wa" data-json='${escapeHtml(JSON.stringify(x))}'>WhatsApp</button></div></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">Belum ada surat.</td></tr>'))}$(document).on('click','.wa',function(){let x=JSON.parse($(this).attr('data-json')),no=x.telepon_ayah||x.telepon_ibu||'';Swal.fire({title:'Kirim Surat WhatsApp',html:`<select id="hub" class="form-select mb-2"><option>Ayah</option><option>Ibu</option><option>Lainnya</option></select><input id="nama" class="form-control mb-2" placeholder="Nama penerima"><input id="no" class="form-control" value="${escapeHtml(no)}" placeholder="Nomor WhatsApp">`,showCancelButton:true,confirmButtonText:'Buka WhatsApp',preConfirm:()=>({hubungan:$('#hub').val(),nama_penerima:$('#nama').val(),nomor:$('#no').val()})}).then(v=>{if(!v.isConfirmed)return;$.post('<?= base_url('surat_tunggakan/siapkan_whatsapp') ?>',{id:x.id,...v.value},r=>{if(r.result==='true'){window.open(r.url,'_blank');history()}else Swal.fire('Gagal',r.message,'error')},'json')})});history();let preset=new URLSearchParams(location.search).get('siswa');if(preset){$.getJSON('<?= base_url('surat_tunggakan/siswa/') ?>'+encodeURIComponent(preset),function(r){if(r.result!=='true')return;let b=$('<button class="pilih d-none"></button>').attr('data-json',JSON.stringify(r.siswa));$('#hasil').append(b);b.trigger('click')})}});</script>
